const DATA = {"matin": [{"ar": "أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ إِنِّي أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَوْمِ وَخَيْرَ مَا بَعْدَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ.", "tr": "Asbahnâ wa asbaha-l-mulku lillâh, wa-l-hamdu lillâh, lâ ilâha illa-llâhu wahdahu lâ sharîka lah, lahu-l-mulku wa lahu-l-hamdu wa huwa 'alâ kulli shay'in qadîr. Rabbi innî as'aluka khayra mâ fî hâdha-l-yawmi wa khayra mâ ba'dah, wa a'ûdhu bika min sharri mâ fî hâdha-l-yawmi wa sharri mâ ba'dah. Rabbi a'ûdhu bika mina-l-kasali wa sû'i-l-kibar. Rabbi a'ûdhu bika min 'adhâbin fi-n-nâri wa 'adhâbin fi-l-qabr.", "fr": "Nous voici au matin et la royauté appartient à Allah. Louange à Allah. Nul ne mérite d'être adoré en dehors d'Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose. Seigneur, je Te demande le bien de ce jour et le bien de ce qui le suit, et je cherche refuge auprès de Toi contre le mal de ce jour et le mal de ce qui le suit. Seigneur, je cherche refuge auprès de Toi contre la paresse et les maux de la vieillesse. Seigneur, je cherche refuge auprès de Toi contre un châtiment dans le Feu et un châtiment dans la tombe.", "src": ["مسلم", "Muslim"], "n": 1, "a": {"hm": 77}}, {"ar": "اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ.", "tr": "Allâhumma bika asbahnâ, wa bika amsaynâ, wa bika nahyâ, wa bika namûtu, wa ilayka-n-nushûr.", "fr": "Ô Allah, c'est par Toi que nous atteignons le matin et par Toi que nous atteignons le soir, par Toi que nous vivons et par Toi que nous mourons, et c'est vers Toi qu'est la résurrection.", "src": ["الترمذي", "at-Tirmidhî"], "n": 1, "a": {"hm": 78}}, {"ar": "اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ.", "tr": "Allâhumma anta rabbî lâ ilâha illâ ant, khalaqtanî wa ana 'abduk, wa ana 'alâ 'ahdika wa wa'dika ma-stata't, a'ûdhu bika min sharri mâ sana't, abû'u laka bi ni'matika 'alayy, wa abû'u bi dhanbî fa-ghfir lî, fa innahu lâ yaghfiru-dh-dhunûba illâ ant.", "fr": "Ô Allah, Tu es mon Seigneur, nul ne mérite d'être adoré en dehors de Toi. Tu m'as créé et je suis Ton serviteur. Je tiens mon engagement et ma promesse envers Toi autant que je le peux. Je cherche refuge auprès de Toi contre le mal que j'ai commis. Je reconnais Ton bienfait envers moi et je reconnais mon péché : pardonne-moi, car nul ne pardonne les péchés en dehors de Toi.", "src": ["البخاري", "al-Bukhârî"], "n": 1, "v": "مَنْ قَالَهَا مُوقِنًا بِهَا حِينَ يُصْبِحُ فَمَاتَ مِنْ يَوْمِهِ دَخَلَ الْجَنَّةَ، وَمَنْ قَالَهَا مُوقِنًا بِهَا حِينَ يُمْسِي فَمَاتَ مِنْ لَيْلَتِهِ دَخَلَ الْجَنَّةَ.", "vf": "Celui qui la dit le matin avec certitude et meurt ce jour-là entre au Paradis ; et celui qui la dit le soir avec certitude et meurt cette nuit-là entre au Paradis.", "a": {"hm": 79}}, {"ar": "اللَّهُمَّ إِنِّي أَصْبَحْتُ أُشْهِدُكَ، وَأُشْهِدُ حَمَلَةَ عَرْشِكَ، وَمَلَائِكَتَكَ، وَجَمِيعَ خَلْقِكَ، أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ.", "tr": "Allâhumma innî asbahtu ush-hiduka, wa ush-hidu hamalata 'arshika, wa malâ'ikataka, wa jamî'a khalqika, annaka anta-llâhu lâ ilâha illâ anta wahdaka lâ sharîka lak, wa anna Muhammadan 'abduka wa rasûluk.", "fr": "Ô Allah, en ce matin je Te prends à témoin, ainsi que les porteurs de Ton Trône, Tes anges et toutes Tes créatures, que Tu es Allah, nul ne mérite d'être adoré en dehors de Toi, Seul, sans associé, et que Muhammad est Ton serviteur et Ton messager.", "src": ["أبو داود", "Abû Dâwûd"], "n": 4, "v": "مَنْ قَالَهَا حِينَ يُصْبِحُ أَوْ يُمْسِي أَرْبَعَ مَرَّاتٍ أَعْتَقَهُ اللَّهُ مِنَ النَّارِ.", "vf": "Celui qui la dit quatre fois le matin ou le soir, Allah l'affranchit du Feu.", "nl": ["٤ مرات", "4 fois"], "a": {"hm": 80}}, {"ar": "اللَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ.", "tr": "Allâhumma mâ asbaha bî min ni'matin aw bi ahadin min khalqika fa minka wahdaka lâ sharîka lak, fa laka-l-hamdu wa laka-sh-shukr.", "fr": "Ô Allah, tout bienfait dont je jouis ce matin, moi ou l'une de Tes créatures, vient de Toi Seul, sans associé. À Toi la louange et à Toi la gratitude.", "src": ["أبو داود", "Abû Dâwûd"], "n": 1, "v": "مَنْ قَالَهَا حِينَ يُصْبِحُ فَقَدْ أَدَّى شُكْرَ يَوْمِهِ، وَمَنْ قَالَهَا حِينَ يُمْسِي فَقَدْ أَدَّى شُكْرَ لَيْلَتِهِ.", "vf": "Celui qui la dit le matin s'est acquitté de la gratitude de sa journée, et celui qui la dit le soir, de celle de sa nuit.", "a": {"hm": 81}}, {"ar": "اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ.", "tr": "Allâhumma 'âfinî fî badanî, Allâhumma 'âfinî fî sam'î, Allâhumma 'âfinî fî basarî, lâ ilâha illâ ant. Allâhumma innî a'ûdhu bika mina-l-kufri wa-l-faqr, wa a'ûdhu bika min 'adhâbi-l-qabr, lâ ilâha illâ ant.", "fr": "Ô Allah, préserve mon corps. Ô Allah, préserve mon ouïe. Ô Allah, préserve ma vue. Nul ne mérite d'être adoré en dehors de Toi. Ô Allah, je cherche refuge auprès de Toi contre la mécréance et la pauvreté, et contre le châtiment de la tombe. Nul ne mérite d'être adoré en dehors de Toi.", "src": ["أحمد", "Ahmad"], "n": 3, "a": {"hm": 82}, "nl": ["٣ مَرَّاتٍ", "3 fois"]}, {"ar": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ.", "tr": "Allâhumma innî a'ûdhu bika mina-l-hammi wa-l-hazan, wa a'ûdhu bika mina-l-'ajzi wa-l-kasal, wa a'ûdhu bika mina-l-jubni wa-l-bukhl, wa a'ûdhu bika min ghalabati-d-dayni wa qahri-r-rijâl.", "fr": "Ô Allah, je cherche refuge auprès de Toi contre le souci et la tristesse, contre l'impuissance et la paresse, contre la lâcheté et l'avarice, contre le poids des dettes et la domination des hommes.", "src": ["أبو داود", "Abû Dâwûd"], "n": 1}, {"ar": "حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ، عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ.", "tr": "Hasbiya-llâhu lâ ilâha illâ huwa, 'alayhi tawakkaltu wa huwa rabbu-l-'arshi-l-'azîm.", "fr": "Allah me suffit, nul ne mérite d'être adoré en dehors de Lui. En Lui je place ma confiance, et Il est le Seigneur du Trône immense.", "src": ["ابن السني", "Ibn as-Sunnî"], "n": 7, "v": "مَنْ قَالَهَا حِينَ يُصْبِحُ وَحِينَ يُمْسِي سَبْعَ مَرَّاتٍ كَفَاهُ اللَّهُ مَا أَهَمَّهُ مِنْ أَمْرِ الدُّنْيَا وَالْآخِرَةِ.", "vf": "Celui qui la dit sept fois le matin et le soir, Allah lui suffit contre ce qui le préoccupe de ce monde et de l'au-delà.", "nl": ["٧ مرات", "7 fois"], "a": {"hm": 83}}, {"ar": "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي، وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي.", "tr": "Allâhumma innî as'aluka-l-'âfiyata fi-d-dunyâ wa-l-âkhirah. Allâhumma innî as'aluka-l-'afwa wa-l-'âfiyata fî dînî wa dunyâya wa ahlî wa mâlî. Allâhumma-stur 'awrâtî, wa âmin raw'âtî. Allâhumma-hfaznî min bayni yadayya, wa min khalfî, wa 'an yamînî, wa 'an shimâlî, wa min fawqî, wa a'ûdhu bi 'azamatika an ughtâla min tahtî.", "fr": "Ô Allah, je Te demande le salut en ce monde et dans l'au-delà. Ô Allah, je Te demande le pardon et le salut dans ma religion, ma vie, ma famille et mes biens. Ô Allah, couvre mes défauts et apaise mes craintes. Ô Allah, protège-moi par-devant et par-derrière, à ma droite et à ma gauche, et d'au-dessus de moi ; et je cherche refuge dans Ta grandeur contre le fait d'être saisi par surprise d'en dessous de moi.", "src": ["أبو داود", "Abû Dâwûd"], "n": 1, "a": {"hm": 84}}, {"ar": "اللَّهُمَّ فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءًا، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ.", "tr": "Allâhumma fâtira-s-samâwâti wa-l-ard, 'âlima-l-ghaybi wa-sh-shahâdah, rabba kulli shay'in wa malîkah, ash-hadu an lâ ilâha illâ ant, a'ûdhu bika min sharri nafsî, wa min sharri-sh-shaytâni wa shirkih, wa an aqtarifa 'alâ nafsî sû'an, aw ajurrahu ilâ muslim.", "fr": "Ô Allah, Créateur des cieux et de la terre, Connaisseur de l'invisible et du visible, Seigneur et Souverain de toute chose, j'atteste que nul ne mérite d'être adoré en dehors de Toi. Je cherche refuge auprès de Toi contre le mal de mon âme, contre le mal de Satan et de son association, et contre le fait de commettre un mal contre moi-même ou de l'attirer sur un musulman.", "src": ["الترمذي", "at-Tirmidhî"], "n": 1, "a": {"hm": 85}}, {"ar": "بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ.", "tr": "Bismi-llâhi-lladhî lâ yadurru ma'a-smihi shay'un fi-l-ardi wa lâ fi-s-samâ', wa huwa-s-samî'u-l-'alîm.", "fr": "Au nom d'Allah, avec le nom duquel rien ne peut nuire, ni sur la terre ni dans le ciel. Il est Celui qui entend tout et sait tout.", "src": ["ابن ماجه", "Ibn Mâjah"], "n": 3, "v": "مَنْ قَالَهَا ثَلَاثًا إِذَا أَصْبَحَ وَثَلَاثًا إِذَا أَمْسَى لَمْ يَضُرَّهُ شَيْءٌ.", "vf": "Celui qui la dit trois fois le matin et trois fois le soir, rien ne lui nuira.", "nl": ["٣ مرات", "3 fois"], "a": {"hm": 86}}, {"ar": "رَضِيتُ بِاللَّهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ ﷺ نَبِيًّا.", "tr": "Radîtu bi-llâhi rabbâ, wa bi-l-islâmi dînâ, wa bi Muhammadin (ﷺ) nabiyyâ.", "fr": "J'agrée Allah comme Seigneur, l'Islam comme religion et Muhammad ﷺ comme Prophète.", "src": ["أحمد", "Ahmad"], "n": 3, "v": "مَنْ قَالَهَا ثَلَاثًا حِينَ يُصْبِحُ وَثَلَاثًا حِينَ يُمْسِي كَانَ حَقًّا عَلَى اللَّهِ أَنْ يُرْضِيَهُ يَوْمَ الْقِيَامَةِ.", "vf": "Celui qui la dit trois fois le matin et trois fois le soir, Allah S'est engagé à le satisfaire le Jour de la Résurrection.", "nl": ["٣ مرات", "3 fois"], "a": {"hm": 87}}, {"ar": "يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ، أَصْلِحْ لِي شَأْنِي كُلَّهُ، وَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ.", "tr": "Yâ Hayyu yâ Qayyûm, bi rahmatika astaghîth, aslih lî sha'nî kullah, wa lâ takilnî ilâ nafsî tarfata 'ayn.", "fr": "Ô Vivant, Ô Celui qui subsiste par Lui-même, c'est par Ta miséricorde que j'implore secours : arrange toutes mes affaires et ne me confie pas à moi-même, ne serait-ce que le temps d'un clin d'œil.", "src": ["الترمذي", "at-Tirmidhî"], "n": 1, "a": {"hm": 88}}, {"ar": "أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ رَبِّ الْعَالَمِينَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذَا الْيَوْمِ: فَتْحَهُ، وَنَصْرَهُ، وَنُورَهُ، وَبَرَكَتَهُ، وَهُدَاهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِيهِ وَشَرِّ مَا بَعْدَهُ.", "tr": "Asbahnâ wa asbaha-l-mulku lillâhi rabbi-l-'âlamîn. Allâhumma innî as'aluka khayra hâdha-l-yawm : fathahu, wa nasrahu, wa nûrahu, wa barakatahu, wa hudâh, wa a'ûdhu bika min sharri mâ fîhi wa sharri mâ ba'dah.", "fr": "Nous voici au matin et la royauté appartient à Allah, Seigneur des mondes. Ô Allah, je Te demande le bien de ce jour : son ouverture, son secours, sa lumière, sa bénédiction et sa guidée ; et je cherche refuge auprès de Toi contre le mal qu'il contient et le mal de ce qui le suit.", "src": ["أبو داود", "Abû Dâwûd"], "n": 1, "a": {"hm": 89}}, {"ar": "أَصْبَحْنَا عَلَى فِطْرَةِ الْإِسْلَامِ، وَعَلَى كَلِمَةِ الْإِخْلَاصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ ﷺ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ.", "tr": "Asbahnâ 'alâ fitrati-l-islâm, wa 'alâ kalimati-l-ikhlâs, wa 'alâ dîni nabiyyinâ Muhammad (ﷺ), wa 'alâ millati abînâ Ibrâhîma hanîfan musliman wa mâ kâna mina-l-mushrikîn.", "fr": "Nous voici au matin sur la saine nature de l'Islam, sur la parole de sincérité, sur la religion de notre Prophète Muhammad ﷺ et sur la voie de notre père Ibrâhîm, monothéiste pur et soumis, qui n'était pas du nombre des associateurs.", "src": ["أحمد", "Ahmad"], "n": 1, "a": {"hm": 90}}, {"ar": "اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا، وَرِزْقًا طَيِّبًا، وَعَمَلًا مُتَقَبَّلًا.", "tr": "Allâhumma innî as'aluka 'ilman nâfi'â, wa rizqan tayyibâ, wa 'amalan mutaqabbalâ.", "fr": "Ô Allah, je Te demande une science utile, une subsistance pure et des œuvres acceptées.", "src": ["ابن ماجه", "Ibn Mâjah"], "n": 1, "a": {"hm": 95}}, {"ar": "اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى نَبِيِّنَا مُحَمَّدٍ.", "tr": "Allâhumma salli wa sallim 'alâ nabiyyinâ Muhammad.", "fr": "Ô Allah, prie sur notre Prophète Muhammad et accorde-lui la paix.", "src": ["الطبراني", "at-Tabarânî"], "n": 10, "v": "قَالَ النَّبِيُّ ﷺ: مَنْ صَلَّى عَلَيَّ حِينَ يُصْبِحُ عَشْرًا وَحِينَ يُمْسِي عَشْرًا أَدْرَكَتْهُ شَفَاعَتِي يَوْمَ الْقِيَامَةِ.", "vf": "Le Prophète ﷺ a dit : « Celui qui prie sur moi dix fois le matin et dix fois le soir obtiendra mon intercession le Jour de la Résurrection. »", "nl": ["١٠ مرات", "10 fois"], "a": {"hm": 98}}, {"ar": "أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ.", "tr": "Astaghfiru-llâha wa atûbu ilayh.", "fr": "Je demande pardon à Allah et je me repens à Lui.", "src": ["البخاري", "al-Bukhârî"], "n": 100, "v": "يَقُولُهَا مِائَةَ مَرَّةٍ فِي الْيَوْمِ.", "vf": "À dire cent fois dans la journée.", "nl": ["١٠٠ مرة", "100 fois"], "a": {"hm": 96}}, {"ar": "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ، وَمِدَادَ كَلِمَاتِهِ.", "tr": "Subhâna-llâhi wa bi hamdih, 'adada khalqih, wa ridâ nafsih, wa zinata 'arshih, wa midâda kalimâtih.", "fr": "Gloire et louange à Allah, autant que le nombre de Ses créatures, autant qu'il Lui plaît, autant que le poids de Son Trône et autant que l'encre de Ses paroles.", "src": ["مسلم", "Muslim"], "n": 3, "v": "يَقُولُهَا ثَلَاثَ مَرَّاتٍ إِذَا أَصْبَحَ.", "vf": "À dire trois fois le matin.", "nl": ["٣ مرات", "3 fois"], "a": {"hm": 94}}, {"ar": "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ.", "tr": "Subhâna-llâhi wa bi hamdih.", "fr": "Gloire et louange à Allah.", "src": ["مسلم", "Muslim"], "n": 100, "v": "مَنْ قَالَهَا مِائَةَ مَرَّةٍ حِينَ يُصْبِحُ وَحِينَ يُمْسِي لَمْ يَأْتِ أَحَدٌ يَوْمَ الْقِيَامَةِ بِأَفْضَلَ مِمَّا جَاءَ بِهِ، إِلَّا أَحَدٌ قَالَ مِثْلَ مَا قَالَ أَوْ زَادَ عَلَيْهِ.", "vf": "Celui qui la dit cent fois le matin et le soir, personne ne viendra le Jour de la Résurrection avec mieux que lui, sauf celui qui en aura dit autant ou davantage.", "nl": ["١٠٠ مرة", "100 fois"], "a": {"hm": 91}}, {"ar": "لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ.", "tr": "Lâ ilâha illa-llâhu wahdahu lâ sharîka lah, lahu-l-mulku wa lahu-l-hamdu wa huwa 'alâ kulli shay'in qadîr.", "fr": "Nul ne mérite d'être adoré en dehors d'Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose.", "src": ["أبو داود والترمذي", "Abû Dâwûd et at-Tirmidhî"], "n": 10, "v": "يَقُولُهَا عَشْرَ مَرَّاتٍ، أَوْ مَرَّةً وَاحِدَةً عِنْدَ الْكَسَلِ. وَمَنْ قَالَهَا مِائَةَ مَرَّةٍ فِي يَوْمٍ كَانَتْ لَهُ عَدْلَ عَشْرِ رِقَابٍ، وَكُتِبَتْ لَهُ مِائَةُ حَسَنَةٍ، وَمُحِيَتْ عَنْهُ مِائَةُ سَيِّئَةٍ، وَكَانَتْ لَهُ حِرْزًا مِنَ الشَّيْطَانِ يَوْمَهُ ذَلِكَ حَتَّى يُمْسِيَ، وَلَمْ يَأْتِ أَحَدٌ بِأَفْضَلَ مِمَّا جَاءَ بِهِ إِلَّا أَحَدٌ عَمِلَ أَكْثَرَ مِنْ ذَلِكَ.", "vf": "À dire dix fois, ou une fois en cas de paresse. Celui qui la dit cent fois dans la journée obtient l'équivalent de l'affranchissement de dix esclaves ; cent bonnes actions lui sont inscrites, cent péchés effacés, et elle le protège de Satan ce jour-là jusqu'au soir. Nul n'apporte mieux que lui, sauf celui qui en a fait davantage.", "nl": ["١٠ أو ١٠٠ مرة", "10 ou 100 fois"], "a": {"hm": 92}}, {"title": ["آيَةُ الْكُرْسِيِّ", "Âyat al-Kursî"], "n": 1, "ar": "اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ وَلَا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ ۝", "tr": "Allâhu lâ ilâha illâ huwa-l-hayyu-l-qayyûm, lâ ta'khudhuhu sinatun wa lâ nawm, lahu mâ fi-s-samâwâti wa mâ fi-l-ard, man dha-lladhî yashfa'u 'indahu illâ bi-idhnih, ya'lamu mâ bayna aydîhim wa mâ khalfahum, wa lâ yuhîtûna bi shay'in min 'ilmihi illâ bimâ shâ', wasi'a kursiyyuhu-s-samâwâti wa-l-ard, wa lâ ya'ûduhu hifzhuhumâ, wa huwa-l-'aliyyu-l-'azîm.", "fr": "Allah ! Nulle divinité en dehors de Lui, le Vivant, Celui qui subsiste par Lui-même. Ni somnolence ni sommeil ne Le saisissent. À Lui appartient tout ce qui est dans les cieux et sur la terre. Qui peut intercéder auprès de Lui sans Sa permission ? Il connaît ce qui est devant eux et ce qui est derrière eux, et ils n'embrassent de Sa science que ce qu'Il veut. Son Kursî s'étend sur les cieux et la terre, dont la garde ne Lui coûte aucune peine. Et Il est le Très-Haut, l'Immense.", "src": ["البقرة ٢٥٥", "Sourate al-Baqara, verset 255"], "q": true, "a": {"q": [262]}}, {"title": ["سُورَةُ الْإِخْلَاصِ", "Sourate al-Ikhlâs"], "n": 3, "nl": ["٣ مَرَّاتٍ", "3 fois"], "ar": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ۝ قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ ۝", "tr": "Bismi-llâhi-r-rahmâni-r-rahîm. Qul huwa-llâhu ahad. Allâhu-s-samad. Lam yalid wa lam yûlad. Wa lam yakun lahu kufuwan ahad.", "fr": "Dis : « Il est Allah, Unique. Allah, Celui vers qui l'on se tourne en tout besoin. Il n'engendre pas et n'a pas été engendré, et nul n'est égal à Lui. »", "src": ["سورة ١١٢", "Sourate 112"], "q": true, "a": {"q": [1, 6222, 6223, 6224, 6225]}}, {"title": ["سُورَةُ الْفَلَقِ", "Sourate al-Falaq"], "n": 3, "nl": ["٣ مَرَّاتٍ", "3 fois"], "ar": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ۝ قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۝ مِنْ شَرِّ مَا خَلَقَ ۝ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ۝ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ۝ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ ۝", "tr": "Bismi-llâhi-r-rahmâni-r-rahîm. Qul a'ûdhu bi rabbi-l-falaq. Min sharri mâ khalaq. Wa min sharri ghâsiqin idhâ waqab. Wa min sharri-n-naffâthâti fi-l-'uqad. Wa min sharri hâsidin idhâ hasad.", "fr": "Dis : « Je cherche refuge auprès du Seigneur de l'aube naissante, contre le mal de ce qu'Il a créé, contre le mal de l'obscurité quand elle s'étend, contre le mal de celles qui soufflent sur les nœuds, et contre le mal de l'envieux quand il envie. »", "src": ["سورة ١١٣", "Sourate 113"], "q": true, "a": {"q": [1, 6226, 6227, 6228, 6229, 6230]}}, {"title": ["سُورَةُ النَّاسِ", "Sourate an-Nâs"], "n": 3, "nl": ["٣ مَرَّاتٍ", "3 fois"], "ar": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ۝ قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ ۝ إِلَهِ النَّاسِ ۝ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ۝ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۝ مِنَ الْجِنَّةِ وَالنَّاسِ ۝", "tr": "Bismi-llâhi-r-rahmâni-r-rahîm. Qul a'ûdhu bi rabbi-n-nâs. Maliki-n-nâs. Ilâhi-n-nâs. Min sharri-l-waswâsi-l-khannâs. Alladhî yuwaswisu fî sudûri-n-nâs. Mina-l-jinnati wa-n-nâs.", "fr": "Dis : « Je cherche refuge auprès du Seigneur des hommes, Souverain des hommes, Dieu des hommes, contre le mal du tentateur furtif, qui souffle le mal dans les poitrines des hommes, qu'il soit djinn ou humain. »", "src": ["سورة ١١٤", "Sourate 114"], "q": true, "a": {"q": [1, 6231, 6232, 6233, 6234, 6235, 6236]}}, {"title": ["دُعَاءُ الْخِتَامِ", "Du'â de clôture"], "n": 1, "ar": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ.", "tr": "Subhânaka-llâhumma wa bi hamdik, ash-hadu an lâ ilâha illâ ant, astaghfiruka wa atûbu ilayk.", "fr": "Gloire et pureté à Toi, ô Allah, et louange à Toi. J'atteste que nul ne mérite d'être adoré en dehors de Toi. Je Te demande pardon et je me repens à Toi.", "src": null, "q": true}], "soir": [{"ar": "أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذِهِ اللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ.", "tr": "Amsaynâ wa amsa-l-mulku lillâh, wa-l-hamdu lillâh, lâ ilâha illa-llâhu wahdahu lâ sharîka lah, lahu-l-mulku wa lahu-l-hamdu wa huwa 'alâ kulli shay'in qadîr. Rabbi as'aluka khayra mâ fî hâdhihi-l-laylati wa khayra mâ ba'dahâ, wa a'ûdhu bika min sharri mâ fî hâdhihi-l-laylati wa sharri mâ ba'dahâ. Rabbi a'ûdhu bika mina-l-kasali wa sû'i-l-kibar. Rabbi a'ûdhu bika min 'adhâbin fi-n-nâri wa 'adhâbin fi-l-qabr.", "fr": "Nous voici au soir et la royauté appartient à Allah. Louange à Allah. Nul ne mérite d'être adoré en dehors d'Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose. Seigneur, je Te demande le bien de cette nuit et le bien de ce qui la suit, et je cherche refuge auprès de Toi contre le mal de cette nuit et le mal de ce qui la suit. Seigneur, je cherche refuge auprès de Toi contre la paresse et les maux de la vieillesse. Seigneur, je cherche refuge auprès de Toi contre un châtiment dans le Feu et un châtiment dans la tombe.", "src": ["مسلم", "Muslim"], "n": 1}, {"ar": "اللَّهُمَّ بِكَ أَمْسَيْنَا، وَبِكَ أَصْبَحْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ الْمَصِيرُ.", "tr": "Allâhumma bika amsaynâ, wa bika asbahnâ, wa bika nahyâ, wa bika namûtu, wa ilayka-l-masîr.", "fr": "Ô Allah, c'est par Toi que nous atteignons le soir et par Toi que nous atteignons le matin, par Toi que nous vivons et par Toi que nous mourons, et c'est vers Toi qu'est le retour.", "src": ["الترمذي", "at-Tirmidhî"], "n": 1}, {"ar": "اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ.", "tr": "Allâhumma anta rabbî lâ ilâha illâ ant, khalaqtanî wa ana 'abduk, wa ana 'alâ 'ahdika wa wa'dika ma-stata't, a'ûdhu bika min sharri mâ sana't, abû'u laka bi ni'matika 'alayy, wa abû'u bi dhanbî fa-ghfir lî, fa innahu lâ yaghfiru-dh-dhunûba illâ ant.", "fr": "Ô Allah, Tu es mon Seigneur, nul ne mérite d'être adoré en dehors de Toi. Tu m'as créé et je suis Ton serviteur. Je tiens mon engagement et ma promesse envers Toi autant que je le peux. Je cherche refuge auprès de Toi contre le mal que j'ai commis. Je reconnais Ton bienfait envers moi et je reconnais mon péché : pardonne-moi, car nul ne pardonne les péchés en dehors de Toi.", "src": ["البخاري", "al-Bukhârî"], "n": 1, "v": "مَنْ قَالَهَا مُوقِنًا بِهَا حِينَ يُصْبِحُ فَمَاتَ مِنْ يَوْمِهِ دَخَلَ الْجَنَّةَ، وَمَنْ قَالَهَا مُوقِنًا بِهَا حِينَ يُمْسِي فَمَاتَ مِنْ لَيْلَتِهِ دَخَلَ الْجَنَّةَ.", "vf": "Celui qui la dit le matin avec certitude et meurt ce jour-là entre au Paradis ; et celui qui la dit le soir avec certitude et meurt cette nuit-là entre au Paradis.", "a": {"hm": 79}}, {"ar": "اللَّهُمَّ إِنِّي أَمْسَيْتُ أُشْهِدُكَ، وَأُشْهِدُ حَمَلَةَ عَرْشِكَ، وَمَلَائِكَتَكَ، وَجَمِيعَ خَلْقِكَ، أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ.", "tr": "Allâhumma innî amsaytu ush-hiduka, wa ush-hidu hamalata 'arshika, wa malâ'ikataka, wa jamî'a khalqika, annaka anta-llâhu lâ ilâha illâ anta wahdaka lâ sharîka lak, wa anna Muhammadan 'abduka wa rasûluk.", "fr": "Ô Allah, en ce soir je Te prends à témoin, ainsi que les porteurs de Ton Trône, Tes anges et toutes Tes créatures, que Tu es Allah, nul ne mérite d'être adoré en dehors de Toi, Seul, sans associé, et que Muhammad est Ton serviteur et Ton messager.", "src": ["أبو داود", "Abû Dâwûd"], "n": 4, "v": "مَنْ قَالَهَا حِينَ يُصْبِحُ أَوْ يُمْسِي أَرْبَعَ مَرَّاتٍ أَعْتَقَهُ اللَّهُ مِنَ النَّارِ.", "vf": "Celui qui la dit quatre fois le matin ou le soir, Allah l'affranchit du Feu.", "nl": ["٤ مرات", "4 fois"]}, {"ar": "اللَّهُمَّ مَا أَمْسَى بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ.", "tr": "Allâhumma mâ amsâ bî min ni'matin aw bi ahadin min khalqika fa minka wahdaka lâ sharîka lak, fa laka-l-hamdu wa laka-sh-shukr.", "fr": "Ô Allah, tout bienfait dont je jouis ce soir, moi ou l'une de Tes créatures, vient de Toi Seul, sans associé. À Toi la louange et à Toi la gratitude.", "src": ["أبو داود", "Abû Dâwûd"], "n": 1, "v": "مَنْ قَالَهَا حِينَ يُصْبِحُ فَقَدْ أَدَّى شُكْرَ يَوْمِهِ، وَمَنْ قَالَهَا حِينَ يُمْسِي فَقَدْ أَدَّى شُكْرَ لَيْلَتِهِ.", "vf": "Celui qui la dit le matin s'est acquitté de la gratitude de sa journée, et celui qui la dit le soir, de celle de sa nuit."}, {"ar": "اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ.", "tr": "Allâhumma 'âfinî fî badanî, Allâhumma 'âfinî fî sam'î, Allâhumma 'âfinî fî basarî, lâ ilâha illâ ant. Allâhumma innî a'ûdhu bika mina-l-kufri wa-l-faqr, wa a'ûdhu bika min 'adhâbi-l-qabr, lâ ilâha illâ ant.", "fr": "Ô Allah, préserve mon corps. Ô Allah, préserve mon ouïe. Ô Allah, préserve ma vue. Nul ne mérite d'être adoré en dehors de Toi. Ô Allah, je cherche refuge auprès de Toi contre la mécréance et la pauvreté, et contre le châtiment de la tombe. Nul ne mérite d'être adoré en dehors de Toi.", "src": ["أحمد", "Ahmad"], "n": 3, "a": {"hm": 82}, "nl": ["٣ مَرَّاتٍ", "3 fois"]}, {"ar": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ.", "tr": "Allâhumma innî a'ûdhu bika mina-l-hammi wa-l-hazan, wa a'ûdhu bika mina-l-'ajzi wa-l-kasal, wa a'ûdhu bika mina-l-jubni wa-l-bukhl, wa a'ûdhu bika min ghalabati-d-dayni wa qahri-r-rijâl.", "fr": "Ô Allah, je cherche refuge auprès de Toi contre le souci et la tristesse, contre l'impuissance et la paresse, contre la lâcheté et l'avarice, contre le poids des dettes et la domination des hommes.", "src": ["أبو داود", "Abû Dâwûd"], "n": 1}, {"ar": "حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ، عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ.", "tr": "Hasbiya-llâhu lâ ilâha illâ huwa, 'alayhi tawakkaltu wa huwa rabbu-l-'arshi-l-'azîm.", "fr": "Allah me suffit, nul ne mérite d'être adoré en dehors de Lui. En Lui je place ma confiance, et Il est le Seigneur du Trône immense.", "src": ["ابن السني", "Ibn as-Sunnî"], "n": 7, "v": "مَنْ قَالَهَا حِينَ يُصْبِحُ وَحِينَ يُمْسِي سَبْعَ مَرَّاتٍ كَفَاهُ اللَّهُ مَا أَهَمَّهُ مِنْ أَمْرِ الدُّنْيَا وَالْآخِرَةِ.", "vf": "Celui qui la dit sept fois le matin et le soir, Allah lui suffit contre ce qui le préoccupe de ce monde et de l'au-delà.", "nl": ["٧ مرات", "7 fois"], "a": {"hm": 83}}, {"ar": "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي، وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي.", "tr": "Allâhumma innî as'aluka-l-'âfiyata fi-d-dunyâ wa-l-âkhirah. Allâhumma innî as'aluka-l-'afwa wa-l-'âfiyata fî dînî wa dunyâya wa ahlî wa mâlî. Allâhumma-stur 'awrâtî, wa âmin raw'âtî. Allâhumma-hfaznî min bayni yadayya, wa min khalfî, wa 'an yamînî, wa 'an shimâlî, wa min fawqî, wa a'ûdhu bi 'azamatika an ughtâla min tahtî.", "fr": "Ô Allah, je Te demande le salut en ce monde et dans l'au-delà. Ô Allah, je Te demande le pardon et le salut dans ma religion, ma vie, ma famille et mes biens. Ô Allah, couvre mes défauts et apaise mes craintes. Ô Allah, protège-moi par-devant et par-derrière, à ma droite et à ma gauche, et d'au-dessus de moi ; et je cherche refuge dans Ta grandeur contre le fait d'être saisi par surprise d'en dessous de moi.", "src": ["أبو داود", "Abû Dâwûd"], "n": 1, "a": {"hm": 84}}, {"ar": "اللَّهُمَّ فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءًا، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ.", "tr": "Allâhumma fâtira-s-samâwâti wa-l-ard, 'âlima-l-ghaybi wa-sh-shahâdah, rabba kulli shay'in wa malîkah, ash-hadu an lâ ilâha illâ ant, a'ûdhu bika min sharri nafsî, wa min sharri-sh-shaytâni wa shirkih, wa an aqtarifa 'alâ nafsî sû'an, aw ajurrahu ilâ muslim.", "fr": "Ô Allah, Créateur des cieux et de la terre, Connaisseur de l'invisible et du visible, Seigneur et Souverain de toute chose, j'atteste que nul ne mérite d'être adoré en dehors de Toi. Je cherche refuge auprès de Toi contre le mal de mon âme, contre le mal de Satan et de son association, et contre le fait de commettre un mal contre moi-même ou de l'attirer sur un musulman.", "src": ["الترمذي", "at-Tirmidhî"], "n": 1, "a": {"hm": 85}}, {"ar": "بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ.", "tr": "Bismi-llâhi-lladhî lâ yadurru ma'a-smihi shay'un fi-l-ardi wa lâ fi-s-samâ', wa huwa-s-samî'u-l-'alîm.", "fr": "Au nom d'Allah, avec le nom duquel rien ne peut nuire, ni sur la terre ni dans le ciel. Il est Celui qui entend tout et sait tout.", "src": ["ابن ماجه", "Ibn Mâjah"], "n": 3, "v": "مَنْ قَالَهَا ثَلَاثًا إِذَا أَصْبَحَ وَثَلَاثًا إِذَا أَمْسَى لَمْ يَضُرَّهُ شَيْءٌ.", "vf": "Celui qui la dit trois fois le matin et trois fois le soir, rien ne lui nuira.", "nl": ["٣ مرات", "3 fois"], "a": {"hm": 86}}, {"ar": "رَضِيتُ بِاللَّهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ ﷺ نَبِيًّا.", "tr": "Radîtu bi-llâhi rabbâ, wa bi-l-islâmi dînâ, wa bi Muhammadin (ﷺ) nabiyyâ.", "fr": "J'agrée Allah comme Seigneur, l'Islam comme religion et Muhammad ﷺ comme Prophète.", "src": ["أحمد", "Ahmad"], "n": 3, "v": "مَنْ قَالَهَا ثَلَاثًا حِينَ يُصْبِحُ وَثَلَاثًا حِينَ يُمْسِي كَانَ حَقًّا عَلَى اللَّهِ أَنْ يُرْضِيَهُ يَوْمَ الْقِيَامَةِ.", "vf": "Celui qui la dit trois fois le matin et trois fois le soir, Allah S'est engagé à le satisfaire le Jour de la Résurrection.", "nl": ["٣ مرات", "3 fois"], "a": {"hm": 87}}, {"ar": "يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ، أَصْلِحْ لِي شَأْنِي كُلَّهُ، وَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ.", "tr": "Yâ Hayyu yâ Qayyûm, bi rahmatika astaghîth, aslih lî sha'nî kullah, wa lâ takilnî ilâ nafsî tarfata 'ayn.", "fr": "Ô Vivant, Ô Celui qui subsiste par Lui-même, c'est par Ta miséricorde que j'implore secours : arrange toutes mes affaires et ne me confie pas à moi-même, ne serait-ce que le temps d'un clin d'œil.", "src": ["الترمذي", "at-Tirmidhî"], "n": 1, "a": {"hm": 88}}, {"ar": "أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ رَبِّ الْعَالَمِينَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذِهِ اللَّيْلَةِ: فَتْحَهَا، وَنَصْرَهَا، وَنُورَهَا، وَبَرَكَتَهَا، وَهُدَاهَا، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِيهَا وَشَرِّ مَا بَعْدَهَا.", "tr": "Amsaynâ wa amsa-l-mulku lillâhi rabbi-l-'âlamîn. Allâhumma innî as'aluka khayra hâdhihi-l-laylah : fat-hahâ, wa nasrahâ, wa nûrahâ, wa barakatahâ, wa hudâhâ, wa a'ûdhu bika min sharri mâ fîhâ wa sharri mâ ba'dahâ.", "fr": "Nous voici au soir et la royauté appartient à Allah, Seigneur des mondes. Ô Allah, je Te demande le bien de cette nuit : son ouverture, son secours, sa lumière, sa bénédiction et sa guidée ; et je cherche refuge auprès de Toi contre le mal qu'elle contient et le mal de ce qui la suit.", "src": ["أبو داود", "Abû Dâwûd"], "n": 1}, {"ar": "أَمْسَيْنَا عَلَى فِطْرَةِ الْإِسْلَامِ، وَعَلَى كَلِمَةِ الْإِخْلَاصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ ﷺ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ.", "tr": "Amsaynâ 'alâ fitrati-l-islâm, wa 'alâ kalimati-l-ikhlâs, wa 'alâ dîni nabiyyinâ Muhammad (ﷺ), wa 'alâ millati abînâ Ibrâhîma hanîfan musliman wa mâ kâna mina-l-mushrikîn.", "fr": "Nous voici au soir sur la saine nature de l'Islam, sur la parole de sincérité, sur la religion de notre Prophète Muhammad ﷺ et sur la voie de notre père Ibrâhîm, monothéiste pur et soumis, qui n'était pas du nombre des associateurs.", "src": ["أحمد", "Ahmad"], "n": 1}, {"ar": "أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ.", "tr": "A'ûdhu bi kalimâti-llâhi-t-tâmmâti min sharri mâ khalaq.", "fr": "Je cherche refuge dans les paroles parfaites d'Allah contre le mal de ce qu'Il a créé.", "v": "مَنْ قَالَهَا حِينَ يُمْسِي ثَلَاثَ مَرَّاتٍ لَمْ تَضُرَّهُ حُمَةٌ تِلْكَ اللَّيْلَةَ.", "vf": "Celui qui la dit trois fois le soir, aucune piqûre venimeuse ne lui nuira cette nuit-là.", "n": 3, "nl": ["٣ مَرَّاتٍ", "3 fois"], "src": ["أحمد والترمذي", "Ahmad et at-Tirmidhî"], "a": {"hm": 97}}, {"ar": "اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى نَبِيِّنَا مُحَمَّدٍ.", "tr": "Allâhumma salli wa sallim 'alâ nabiyyinâ Muhammad.", "fr": "Ô Allah, prie sur notre Prophète Muhammad et accorde-lui la paix.", "src": ["الطبراني", "at-Tabarânî"], "n": 10, "v": "قَالَ النَّبِيُّ ﷺ: مَنْ صَلَّى عَلَيَّ حِينَ يُصْبِحُ عَشْرًا وَحِينَ يُمْسِي عَشْرًا أَدْرَكَتْهُ شَفَاعَتِي يَوْمَ الْقِيَامَةِ.", "vf": "Le Prophète ﷺ a dit : « Celui qui prie sur moi dix fois le matin et dix fois le soir obtiendra mon intercession le Jour de la Résurrection. »", "nl": ["١٠ مرات", "10 fois"], "a": {"hm": 98}}, {"ar": "أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ.", "tr": "Astaghfiru-llâha wa atûbu ilayh.", "fr": "Je demande pardon à Allah et je me repens à Lui.", "src": ["البخاري", "al-Bukhârî"], "n": 100, "v": "يَقُولُهَا مِائَةَ مَرَّةٍ فِي الْيَوْمِ.", "vf": "À dire cent fois dans la journée.", "nl": ["١٠٠ مرة", "100 fois"], "a": {"hm": 96}}, {"ar": "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ.", "tr": "Subhâna-llâhi wa bi hamdih.", "fr": "Gloire et louange à Allah.", "src": ["مسلم", "Muslim"], "n": 100, "v": "مَنْ قَالَهَا مِائَةَ مَرَّةٍ حِينَ يُصْبِحُ وَحِينَ يُمْسِي لَمْ يَأْتِ أَحَدٌ يَوْمَ الْقِيَامَةِ بِأَفْضَلَ مِمَّا جَاءَ بِهِ، إِلَّا أَحَدٌ قَالَ مِثْلَ مَا قَالَ أَوْ زَادَ عَلَيْهِ.", "vf": "Celui qui la dit cent fois le matin et le soir, personne ne viendra le Jour de la Résurrection avec mieux que lui, sauf celui qui en aura dit autant ou davantage.", "nl": ["١٠٠ مرة", "100 fois"], "a": {"hm": 91}}, {"ar": "لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ.", "tr": "Lâ ilâha illa-llâhu wahdahu lâ sharîka lah, lahu-l-mulku wa lahu-l-hamdu wa huwa 'alâ kulli shay'in qadîr.", "fr": "Nul ne mérite d'être adoré en dehors d'Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose.", "src": ["أبو داود والترمذي", "Abû Dâwûd et at-Tirmidhî"], "n": 10, "v": "يَقُولُهَا عَشْرَ مَرَّاتٍ، أَوْ مَرَّةً وَاحِدَةً عِنْدَ الْكَسَلِ. وَمَنْ قَالَهَا مِائَةَ مَرَّةٍ فِي يَوْمٍ كَانَتْ لَهُ عَدْلَ عَشْرِ رِقَابٍ، وَكُتِبَتْ لَهُ مِائَةُ حَسَنَةٍ، وَمُحِيَتْ عَنْهُ مِائَةُ سَيِّئَةٍ، وَكَانَتْ لَهُ حِرْزًا مِنَ الشَّيْطَانِ يَوْمَهُ ذَلِكَ حَتَّى يُمْسِيَ، وَلَمْ يَأْتِ أَحَدٌ بِأَفْضَلَ مِمَّا جَاءَ بِهِ إِلَّا أَحَدٌ عَمِلَ أَكْثَرَ مِنْ ذَلِكَ.", "vf": "À dire dix fois, ou une fois en cas de paresse. Celui qui la dit cent fois dans la journée obtient l'équivalent de l'affranchissement de dix esclaves ; cent bonnes actions lui sont inscrites, cent péchés effacés, et elle le protège de Satan ce jour-là jusqu'au soir. Nul n'apporte mieux que lui, sauf celui qui en a fait davantage.", "nl": ["١٠ أو ١٠٠ مرة", "10 ou 100 fois"], "a": {"hm": 92}}, {"title": ["آيَةُ الْكُرْسِيِّ", "Âyat al-Kursî"], "n": 1, "ar": "اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ وَلَا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ ۝", "tr": "Allâhu lâ ilâha illâ huwa-l-hayyu-l-qayyûm, lâ ta'khudhuhu sinatun wa lâ nawm, lahu mâ fi-s-samâwâti wa mâ fi-l-ard, man dha-lladhî yashfa'u 'indahu illâ bi-idhnih, ya'lamu mâ bayna aydîhim wa mâ khalfahum, wa lâ yuhîtûna bi shay'in min 'ilmihi illâ bimâ shâ', wasi'a kursiyyuhu-s-samâwâti wa-l-ard, wa lâ ya'ûduhu hifzhuhumâ, wa huwa-l-'aliyyu-l-'azîm.", "fr": "Allah ! Nulle divinité en dehors de Lui, le Vivant, Celui qui subsiste par Lui-même. Ni somnolence ni sommeil ne Le saisissent. À Lui appartient tout ce qui est dans les cieux et sur la terre. Qui peut intercéder auprès de Lui sans Sa permission ? Il connaît ce qui est devant eux et ce qui est derrière eux, et ils n'embrassent de Sa science que ce qu'Il veut. Son Kursî s'étend sur les cieux et la terre, dont la garde ne Lui coûte aucune peine. Et Il est le Très-Haut, l'Immense.", "src": ["البقرة ٢٥٥", "Sourate al-Baqara, verset 255"], "q": true, "a": {"q": [262]}}, {"title": ["آخِرُ سُورَةِ الْبَقَرَةِ", "Fin de la sourate al-Baqara"], "n": 1, "q": true, "ar": "آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ۝ لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ ۝", "tr": "Âmana-r-rasûlu bimâ unzila ilayhi min rabbihi wa-l-mu'minûn, kullun âmana bi-llâhi wa malâ'ikatihi wa kutubihi wa rusulih, lâ nufarriqu bayna ahadin min rusulih, wa qâlû sami'nâ wa ata'nâ, ghufrânaka rabbanâ wa ilayka-l-masîr. Lâ yukallifu-llâhu nafsan illâ wus'ahâ, lahâ mâ kasabat wa 'alayhâ ma-ktasabat, rabbanâ lâ tu'âkhidhnâ in nasînâ aw akhta'nâ, rabbanâ wa lâ tahmil 'alaynâ isran kamâ hamaltahu 'ala-lladhîna min qablinâ, rabbanâ wa lâ tuhammilnâ mâ lâ tâqata lanâ bih, wa-'fu 'annâ, wa-ghfir lanâ, wa-rhamnâ, anta mawlânâ fa-nsurnâ 'ala-l-qawmi-l-kâfirîn.", "fr": "Le Messager a cru en ce qu'on a fait descendre vers lui de la part de son Seigneur, ainsi que les croyants : tous ont cru en Allah, en Ses anges, en Ses Livres et en Ses messagers. « Nous ne faisons aucune distinction entre Ses messagers. » Et ils ont dit : « Nous avons entendu et obéi. Pardon, Seigneur ! C'est vers Toi qu'est le retour. » Allah n'impose à aucune âme une charge au-delà de sa capacité. Elle aura le bien qu'elle aura acquis, et supportera le mal qu'elle aura commis. « Seigneur, ne nous tiens pas rigueur de nos oublis et de nos erreurs. Seigneur, ne nous charge pas d'un fardeau comme celui dont Tu as chargé ceux qui nous ont précédés. Seigneur, ne nous impose pas ce que nous ne pouvons supporter. Efface nos fautes, pardonne-nous et fais-nous miséricorde. Tu es notre Maître : accorde-nous la victoire sur le peuple des mécréants. »", "v": "مَنْ قَرَأَ بِالْآيَتَيْنِ مِنْ آخِرِ سُورَةِ الْبَقَرَةِ فِي لَيْلَةٍ كَفَتَاهُ.", "vf": "Celui qui récite les deux derniers versets de la sourate al-Baqara pendant la nuit, ils lui suffiront.", "src": ["البقرة ٢٨٥–٢٨٦ · رواه البخاري ومسلم", "al-Baqara 285–286 · hadith rapporté par al-Bukhârî et Muslim"], "a": {"q": [292, 293]}}, {"title": ["سُورَةُ الْإِخْلَاصِ", "Sourate al-Ikhlâs"], "n": 3, "nl": ["٣ مَرَّاتٍ", "3 fois"], "ar": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ۝ قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ ۝", "tr": "Bismi-llâhi-r-rahmâni-r-rahîm. Qul huwa-llâhu ahad. Allâhu-s-samad. Lam yalid wa lam yûlad. Wa lam yakun lahu kufuwan ahad.", "fr": "Dis : « Il est Allah, Unique. Allah, Celui vers qui l'on se tourne en tout besoin. Il n'engendre pas et n'a pas été engendré, et nul n'est égal à Lui. »", "src": ["سورة ١١٢", "Sourate 112"], "q": true, "a": {"q": [1, 6222, 6223, 6224, 6225]}}, {"title": ["سُورَةُ الْفَلَقِ", "Sourate al-Falaq"], "n": 3, "nl": ["٣ مَرَّاتٍ", "3 fois"], "ar": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ۝ قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۝ مِنْ شَرِّ مَا خَلَقَ ۝ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ۝ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ۝ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ ۝", "tr": "Bismi-llâhi-r-rahmâni-r-rahîm. Qul a'ûdhu bi rabbi-l-falaq. Min sharri mâ khalaq. Wa min sharri ghâsiqin idhâ waqab. Wa min sharri-n-naffâthâti fi-l-'uqad. Wa min sharri hâsidin idhâ hasad.", "fr": "Dis : « Je cherche refuge auprès du Seigneur de l'aube naissante, contre le mal de ce qu'Il a créé, contre le mal de l'obscurité quand elle s'étend, contre le mal de celles qui soufflent sur les nœuds, et contre le mal de l'envieux quand il envie. »", "src": ["سورة ١١٣", "Sourate 113"], "q": true, "a": {"q": [1, 6226, 6227, 6228, 6229, 6230]}}, {"title": ["سُورَةُ النَّاسِ", "Sourate an-Nâs"], "n": 3, "nl": ["٣ مَرَّاتٍ", "3 fois"], "ar": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ۝ قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ ۝ إِلَهِ النَّاسِ ۝ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ۝ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۝ مِنَ الْجِنَّةِ وَالنَّاسِ ۝", "tr": "Bismi-llâhi-r-rahmâni-r-rahîm. Qul a'ûdhu bi rabbi-n-nâs. Maliki-n-nâs. Ilâhi-n-nâs. Min sharri-l-waswâsi-l-khannâs. Alladhî yuwaswisu fî sudûri-n-nâs. Mina-l-jinnati wa-n-nâs.", "fr": "Dis : « Je cherche refuge auprès du Seigneur des hommes, Souverain des hommes, Dieu des hommes, contre le mal du tentateur furtif, qui souffle le mal dans les poitrines des hommes, qu'il soit djinn ou humain. »", "src": ["سورة ١١٤", "Sourate 114"], "q": true, "a": {"q": [1, 6231, 6232, 6233, 6234, 6235, 6236]}}, {"title": ["دُعَاءُ الْخِتَامِ", "Du'â de clôture"], "n": 1, "ar": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ.", "tr": "Subhânaka-llâhumma wa bi hamdik, ash-hadu an lâ ilâha illâ ant, astaghfiruka wa atûbu ilayk.", "fr": "Gloire et pureté à Toi, ô Allah, et louange à Toi. J'atteste que nul ne mérite d'être adoré en dehors de Toi. Je Te demande pardon et je me repens à Toi.", "src": null, "q": true}]};
const SESS = {
  matin: { items: DATA.matin, ar: "أَذْكَارُ الصَّبَاحِ", fr: "Invocations du matin", doneAr: "تَقَبَّلَ اللَّهُ مِنَّا وَمِنْكُمْ", doneFr: "Invocations du matin terminées" },
  soir:  { items: DATA.soir,  ar: "أَذْكَارُ الْمَسَاءِ", fr: "Invocations du soir",  doneAr: "تَقَبَّلَ اللَّهُ مِنَّا وَمِنْكُمْ", doneFr: "Invocations du soir terminées" }
};
const SUN = '<svg width="36" height="36" viewBox="0 0 48 48" fill="none" stroke="#E3B65E" stroke-width="2.8" stroke-linecap="round"><path d="M14 32a10 10 0 0 1 20 0"/><path d="M6 32h36M24 12v5M11 18l3.5 3.5M37 18l-3.5 3.5"/></svg>';
const MOON = '<svg width="34" height="34" viewBox="0 0 48 48" fill="#E3B65E"><path d="M30 8a16 16 0 1 0 10 28A14 14 0 0 1 30 8z"/><circle cx="36" cy="14" r="2" fill="#F7F1E3"/></svg>';
const AR = "٠١٢٣٤٥٦٧٨٩";
const an = n => String(n).replace(/\d/g, d => AR[d]);
const esc = s => String(s).replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const today = () => { const d = new Date(); return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0"); };
const store = {
  get(k, def){ try { const v = localStorage.getItem(k); return v ? JSON.parse(v) : def; } catch(e){ return def; } },
  set(k, v){ try { localStorage.setItem(k, JSON.stringify(v)); } catch(e){} }
};

let prefs = Object.assign({tr:true, fr:true, scale:1, vib:true, snd:false, auto:false, rate:1}, store.get("wirdi-prefs", {}));
const progs = {};
function loadProg(k){
  let p = store.get("wirdi-prog-" + k, null);
  if (!p || p.day !== today()) p = {day: today(), counts: {}, idx: 0};
  progs[k] = p; return p;
}
loadProg("matin"); loadProg("soir");

let cur = null;      // null = accueil, sinon "matin" | "soir"
let idx = 0;
const C = 2 * Math.PI * 52;
const $ = id => document.getElementById(id);
const main = $("main"), app = $("app"), root = document.documentElement;

const items = () => SESS[cur].items;
const prog = () => progs[cur];
function save(){ if (!cur || cur === "coran" || cur === "learn") return; prog().idx = idx; store.set("wirdi-prog-" + cur, prog()); }
function savePrefs(){ store.set("wirdi-prefs", prefs); }
function doneOfK(k, i){ return progs[k].counts[i] || 0; }
function isDoneK(k, i){ return doneOfK(k, i) >= SESS[k].items[i].n; }
function doneCountK(k){ return SESS[k].items.reduce((s, _, i) => s + (isDoneK(k, i) ? 1 : 0), 0); }
const doneOf = i => doneOfK(cur, i), isDone = i => isDoneK(cur, i), doneCount = () => doneCountK(cur);

function applyPrefs(){
  app.classList.toggle("hide-tr", !prefs.tr);
  app.classList.toggle("hide-fr", !prefs.fr);
  root.style.setProperty("--scale", prefs.scale);
  $("swTr").setAttribute("aria-checked", prefs.tr);
  $("swFr").setAttribute("aria-checked", prefs.fr);
  $("swVib").setAttribute("aria-checked", prefs.vib);
  $("swSnd").setAttribute("aria-checked", prefs.snd);
  $("swAuto").setAttribute("aria-checked", prefs.auto);
  document.querySelectorAll("[data-rate]").forEach(b => b.classList.toggle("on", +b.dataset.rate === prefs.rate));
}

