function frDate(){
  const d = new Date();
  let g = "", h = "";
  try { g = new Intl.DateTimeFormat("fr-FR", {weekday: "long", day: "numeric", month: "long"}).format(d); } catch(e){}
  try { h = new Intl.DateTimeFormat("fr-FR-u-ca-islamic-umalqura", {day: "numeric", month: "long", year: "numeric"}).format(d).replace(/\s?AH$/i, " H"); } catch(e){}
  return (g ? g.charAt(0).toUpperCase() + g.slice(1) : "") + (h ? " · " + h : "");
}
