    s += '<button class="sess2 ' + k + (k === suggest ? ' now' : '') + '" data-k="' + k + '">' + ART[k]
      + '<span class="s-top">' + (k === suggest && !fin ? '<span class="chip">' + (k === "matin" ? "C'est le moment" : "C'est le moment") + '</span>' : '<span></span>') + '</span>'
