      + '<span class="s-bot"><span class="ringw"><svg viewBox="0 0 46 46" width="46" height="46"><circle cx="23" cy="23" r="' + R + '" fill="none" stroke-width="4" class="rb"/><circle cx="23" cy="23" r="' + R + '" fill="none" stroke-width="4" stroke-linecap="round" class="rf" style="stroke-dasharray:' + CC + ';stroke-dashoffset:' + (CC * (1 - n / tot)) + '"/></svg><span class="rn">' + (fin ? "✓" : n) + '</span></span>'
      + '<span class="s-st"><b>' + status + '</b><small>' + n + ' / ' + tot + ' invocations</small></span>'
