// ---------- Audio ----------
const HM = id => ["https://www.hisnmuslim.com/audio/ar/" + id + ".mp3"];
const QA = n => ["https://cdn.islamic.app/quran/audio/ar.alafasy/" + n + ".mp3", "https://cdn.islamic.network/quran/audio/128/ar.alafasy/" + n + ".mp3"];
const player = new Audio();
player.preload = "none";
let pl = {k: null, tracks: [], ti: 0, alt: 0, state: "idle"};
let autoChain = false;
function tracksOf(it){ if (!it || !it.a) return null; return it.a.hm ? [HM(it.a.hm)] : it.a.q.map(QA); }
function curKey(){ return cur === null ? null : cur + ":" + idx; }
function setAudioUI(state){
  pl.state = state;
  const b = $("bPlay"); if (!b || pl.k !== curKey()) { if (b) paintPlay(b, "idle"); return; }
  paintPlay(b, state);
}
function paintPlay(b, state){
  b.className = "play " + state;
  const lab = {idle:"Écouter", loading:"Chargement…", playing:"Pause", error:"Audio indisponible"}[state];
  b.querySelector("span").textContent = lab;
  b.querySelector("svg").innerHTML = state === "playing" ? '<rect x="6" y="5" width="4" height="14" rx="1"/><rect x="14" y="5" width="4" height="14" rx="1"/>' : '<path d="M8 5.5v13a1 1 0 0 0 1.5.86l10-6.5a1 1 0 0 0 0-1.72l-10-6.5A1 1 0 0 0 8 5.5z"/>';
  b.setAttribute("aria-label", lab);
}
function loadTrack(){
  player.src = pl.tracks[pl.ti][pl.alt];
  player.playbackRate = prefs.rate;
  setAudioUI("loading");
  const token = pl, src = player.src;
  const p = player.play();
  if (p && p.catch) p.catch(e => { if (pl === token && player.src === src && e && e.name === "NotAllowedError") setAudioUI("idle"); });
}
function onAudioErr(){
  if (pl.k === null) return;
  if (pl.alt < pl.tracks[pl.ti].length - 1) { pl.alt++; loadTrack(); }
  else setAudioUI("error");
}
player.addEventListener("error", onAudioErr);
player.addEventListener("playing", () => { player.playbackRate = prefs.rate; setAudioUI("playing"); });
player.addEventListener("waiting", () => setAudioUI("loading"));
player.addEventListener("ended", () => {
  if (pl.k === null) return;
  if (pl.ti < pl.tracks.length - 1) { pl.ti++; pl.alt = 0; loadTrack(); return; }
  setAudioUI("idle");
  if (prefs.auto && pl.k === curKey()) autoCount();
});
function startAudio(){
  const t = tracksOf(items()[idx]); if (!t) return;
  if (typeof lpReset === "function") lpReset();
  pl = {k: curKey(), tracks: t, ti: 0, alt: 0, state: "loading"};
  loadTrack();
}
function stopAudio(){
  try { player.pause(); } catch(e){}
  pl.k = null; setAudioUI("idle");
}
function toggleAudio(){
  if (pl.k === curKey() && (pl.state === "playing" || pl.state === "loading")) { stopAudio(); autoChain = false; return; }
  startAudio();
}
function autoCount(){
  if (cur === null || idx >= items().length) return;
  const it = items()[idx];
  if (doneOf(idx) >= it.n) return;
  const before = doneOf(idx);
  tap();
  if (doneOf(idx) < it.n) startAudio();
  else if (before < it.n) autoChain = true;
}
if ("mediaSession" in navigator) { try { navigator.mediaSession.metadata = new MediaMetadata({title: "Wirdî", artist: "Invocations du matin et du soir"}); } catch(e){} }

function renderCard(i){
  const it = items()[i];
  let h = '<article class="card">';
  h += '<div class="meta"><span class="num">' + an(i + 1) + '</span>';
  if (it.nl) h += '<span class="pill"><span class="a">' + esc(it.nl[0]) + '</span><span class="l">× ' + esc(it.nl[1]) + '</span></span>';
  if (it.a) h += '<button class="play idle" id="bPlay" aria-label="Écouter"><svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor"></svg><span>Écouter</span></button>';
  h += '</div>';
  if (it.title) h += '<div class="title" dir="rtl">' + esc(it.title[0]) + '<small dir="ltr">' + esc(it.title[1]) + '</small></div>';
  h += '<p class="ar" lang="ar">' + esc(it.ar) + '</p>';
  h += '<p class="tr">' + esc(it.tr) + '</p>';
  h += '<p class="fr">' + esc(it.fr) + '</p>';
  if (it.v) h += '<div class="virtue"><span class="virtue-h">Mérite</span><p class="va" lang="ar">' + esc(it.v) + '</p><p class="vf">' + esc(it.vf) + '</p></div>';
  if (it.src) h += '<div class="src"><span class="a">' + (it.q ? '' : 'رواه ') + esc(it.src[0]) + '</span><span class="l">' + (it.q ? '' : 'Rapporté par ') + esc(it.src[1]) + '</span></div>';
  return h + '</article>';
}

function renderEnd(){
  return '<div class="end">' + (cur === "matin" ? SUN.replace(/36/g, "84") : MOON.replace(/34/g, "80"))
    + '<h2>' + SESS[cur].doneAr + '</h2>'
    + '<p>' + SESS[cur].doneFr + ' : ' + doneCount() + ' sur ' + items().length + '.</p>'
    + '<button class="btn" id="bHome">Retour à l\'accueil</button>'
    + '<button class="btn ghost" id="bReview">Revoir les invocations</button></div>';
}


