const JUZ = [[1,1],[2,142],[2,253],[3,93],[4,24],[4,148],[5,82],[6,111],[7,88],[8,41],[9,93],[11,6],[12,53],[15,1],[17,1],[18,75],[21,1],[23,1],[25,21],[27,56],[29,46],[33,31],[36,28],[39,32],[41,47],[46,1],[51,31],[58,1],[67,1],[78,1]];
let Q = null, qLoading = null, qErr = false;
const qv = {mode: "list", tab: "s", s: 1, a: 1, filter: ""};
function loadQuran(){
  if (Q) return Promise.resolve(Q);
  if (qLoading) return qLoading;
  qLoading = fetch("quran-uthmani.txt", {cache: "no-cache"}).then(r => { if (!r.ok) throw new Error("absent"); return r.text(); }).then(txt => {
    const S = Array.from({length: 115}, () => []);
    let n = 0;
    for (const line of txt.split(/\r?\n/)){
      if (!line || line[0] === "#") continue;
      const p = line.split("|"); if (p.length < 3) continue;
      const s = +p[0], a = +p[1]; if (!(s >= 1 && s <= 114)) continue;
      S[s][a - 1] = p.slice(2).join("|").trim(); n++;
    }
    if (n < 6000) throw new Error("incomplet");
    Q = S; return Q;
  }).catch(e => { qErr = true; qLoading = null; throw e; });
  return qLoading;
}
const BASM_RE = /^(بِسْمِ\s+\S+\s+\S+\s+\S+)\s+/;
function juzOf(s, a){ let j = 1; JUZ.forEach((x, i) => { if (s > x[0] || (s === x[0] && a >= x[1])) j = i + 1; }); return j; }
const qLast = () => store.get("wirdi-quran-last", null);
const qMark = () => store.get("wirdi-quran-mark", null);
function qToast(msg){
  let t = $("qToast"); if (!t){ t = document.createElement("div"); t.id = "qToast"; t.className = "toast"; document.body.appendChild(t); }
  t.textContent = msg; t.classList.add("show"); clearTimeout(t._h); t._h = setTimeout(() => t.classList.remove("show"), 2200);
}
function openQuran(){ stopAudio(); cur = "coran"; qv.mode = "list"; render(); }
function openSura(s, a){ qv.mode = "read"; qv.s = s; qv.a = a || 1; render(); }

function renderQuran(){
  if (!Q){
    main.innerHTML = '<div class="qwrap"><p class="qmsg">Chargement du Coran…</p></div>';
    loadQuran().then(() => { if (cur === "coran") render(); }).catch(() => {
      if (cur !== "coran") return;
      main.innerHTML = '<div class="qwrap"><div class="qmsg"><b>Le texte du Coran n’est pas disponible.</b><br>Vérifiez votre connexion. Pour l’administrateur : le fichier <code>quran-uthmani.txt</code> (Tanzil) doit se trouver à la racine du site.</div></div>';
    });
    return;
  }
  if (qv.mode === "read") return renderSura();
  const last = qLast(), mark = qMark();
  let h = '<div class="qwrap">';
  if (last) h += '<button class="qresume" data-s="' + last.s + '" data-a="' + last.a + '"><span class="qr-l"><small>Reprendre la lecture</small><b>' + esc(SURA_TR[last.s - 1]) + ' · verset ' + last.a + '</b></span><span class="qr-ar" lang="ar">' + SURA_AR[last.s - 1] + '</span></button>';
  if (mark) h += '<button class="qresume mark" data-s="' + mark.s + '" data-a="' + mark.a + '"><span class="qr-l"><small>🔖 Marque-page</small><b>' + esc(SURA_TR[mark.s - 1]) + ' · verset ' + mark.a + '</b></span><span class="qr-ar" lang="ar">' + SURA_AR[mark.s - 1] + '</span></button>';
  h += '<div class="qtabs"><button data-tab="s" class="' + (qv.tab === "s" ? "on" : "") + '">Sourates</button><button data-tab="j" class="' + (qv.tab === "j" ? "on" : "") + '">Juz’</button></div>';
  if (qv.tab === "s") h += '<input class="qsearch" id="qSearch" type="search" placeholder="Rechercher une sourate (nom ou numéro)" value="' + esc(qv.filter) + '">';
  h += '<div class="qlist" id="qList"></div></div>';
  main.innerHTML = h;
  main.querySelectorAll(".qresume").forEach(b => b.onclick = () => openSura(+b.dataset.s, +b.dataset.a));
  main.querySelectorAll("[data-tab]").forEach(b => b.onclick = () => { qv.tab = b.dataset.tab; render(); });
  const inp = $("qSearch"); if (inp) inp.oninput = () => { qv.filter = inp.value; fillQList(); };
  fillQList();
}
function norm(s){ return s.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f'’\- ]/g, "").replace(/[\u064B-\u0652\u0670]/g, "").replace(/[أإآ]/g, "ا"); }
function fillQList(){
  const box = $("qList"); if (!box) return;
  let h = "";
  if (qv.tab === "s"){
    const f = norm(qv.filter.trim());
    for (let s = 1; s <= 114; s++){
      if (f && !(String(s) === qv.filter.trim() || norm(SURA_TR[s - 1]).includes(f) || norm(SURA_AR[s - 1]).includes(f))) continue;
      h += '<button class="qrow" data-s="' + s + '"><span class="qn">' + s + '</span><span class="qt"><b>' + esc(SURA_TR[s - 1]) + '</b><small>' + Q[s].length + ' versets</small></span><span class="qa" lang="ar">' + SURA_AR[s - 1] + '</span></button>';
    }
    if (!h) h = '<p class="qmsg">Aucune sourate trouvée.</p>';
  } else {
    JUZ.forEach((x, i) => {
      h += '<button class="qrow" data-s="' + x[0] + '" data-a="' + x[1] + '"><span class="qn">' + (i + 1) + '</span><span class="qt"><b>Juz’ ' + (i + 1) + '</b><small>' + esc(SURA_TR[x[0] - 1]) + ' ' + x[0] + ':' + x[1] + '</small></span><span class="qa" lang="ar">الجزء ' + an(i + 1) + '</span></button>';
    });
  }
  box.innerHTML = h;
  box.querySelectorAll(".qrow").forEach(b => b.onclick = () => openSura(+b.dataset.s, +(b.dataset.a || 1)));
}

function renderSura(){
  const s = qv.s, V = Q[s];
  const mark = qMark();
  let h = '<div class="qread"><div class="sura-head"><span class="sh-ar" lang="ar">سُورَةُ ' + SURA_AR[s - 1] + '</span><span class="sh-fr">' + s + '. ' + esc(SURA_TR[s - 1]) + ' · ' + V.length + ' versets · juz’ ' + juzOf(s, 1) + '</span></div>';
  let body = "";
  V.forEach((t, i) => {
    let txt = t;
    if (i === 0 && s !== 1 && s !== 9){
      const m = txt.match(BASM_RE);
      if (m){ h += '<p class="basmala" lang="ar">' + esc(m[1]) + '</p>'; txt = txt.slice(m[0].length); }
    }
    const isMark = mark && mark.s === s && mark.a === i + 1;
    body += '<span class="aya' + (isMark ? " marked" : "") + '" data-a="' + (i + 1) + '">' + esc(txt) + ' <span class="an">﴿' + an(i + 1) + '﴾</span></span> ';
  });
  if (s === 9) h += '<p class="qnote">Cette sourate ne commence pas par la basmala.</p>';
  h += '<div class="mushaf" lang="ar" dir="rtl">' + body + '</div>';
  h += '<div class="qnav">'
    + (s > 1 ? '<button class="btn ghost" data-go="' + (s - 1) + '">‹ ' + esc(SURA_TR[s - 2]) + '</button>' : '<span></span>')
    + (s < 114 ? '<button class="btn" data-go="' + (s + 1) + '">' + esc(SURA_TR[s]) + ' ›</button>' : '<span></span>') + '</div>';
  h += '<p class="qcredit">Texte : Tanzil Quran Text (Uthmani) · tanzil.net<br>Touchez un verset pour y placer le marque-page.</p></div>';
  main.innerHTML = h;
  main.querySelectorAll("[data-go]").forEach(b => b.onclick = () => openSura(+b.dataset.go, 1));
  main.querySelectorAll(".aya").forEach(el => el.onclick = () => {
    const a = +el.dataset.a;
    store.set("wirdi-quran-mark", {s, a});
    main.querySelectorAll(".aya.marked").forEach(x => x.classList.remove("marked"));
    el.classList.add("marked");
    qToast("🔖 Marque-page : " + SURA_TR[s - 1] + ", verset " + a);
  });
  const target = main.querySelector('.aya[data-a="' + qv.a + '"]');
  if (target && qv.a > 1) requestAnimationFrame(() => { main.scrollTop = target.offsetTop - main.offsetTop - 20; });
  else main.scrollTop = 0;
  store.set("wirdi-quran-last", {s, a: qv.a});
}
let qScrollT = null;
main.addEventListener("scroll", () => {
  if (cur !== "coran" || qv.mode !== "read") return;
  clearTimeout(qScrollT);
  qScrollT = setTimeout(() => {
    const top = main.getBoundingClientRect().top + 10;
    for (const el of main.querySelectorAll(".aya")){
      const r = el.getBoundingClientRect();
      if (r.bottom > top){ const a = +el.dataset.a; qv.a = a; store.set("wirdi-quran-last", {s: qv.s, a}); break; }
    }
  }, 300);
}, {passive: true});


