let lp = null;
function lpReset(){ if (lp) lp.classList.remove("playing"); lp = null; }
function learnPlay(btn, urls){
  const same = lp === btn;
  stopAudio(); lpReset();
  if (same) return;
  lp = btn; lp._u = urls; lp._a = 0; btn.classList.add("playing"); btn.classList.remove("err");
  player.src = urls[0]; player.playbackRate = prefs.rate;
  const p = player.play(); if (p && p.catch) p.catch(() => {});
}
player.addEventListener("ended", () => { if (lp) lpReset(); });
player.addEventListener("error", () => {
  if (!lp) return;
  if (lp._a < lp._u.length - 1){ lp._a++; player.src = lp._u[lp._a]; const p = player.play(); if (p && p.catch) p.catch(() => {}); }
  else { lp.classList.add("err"); lpReset(); }
});

