function openLearn(mode, extra){ stopAudio(); lpReset(); lv.mode = mode; Object.assign(lv, extra || {}); render(); main.scrollTop = 0; }
function renderLearn(){
  const m = lv.mode;
  if (m === "home") return learnHome();
  if (m === "alpha") return learnAlpha();
  if (m === "letter") return learnLetter();
  if (m === "vowels") return learnVowels();
  if (m === "syll") return learnSyll();
  if (m === "vocab") return learnList(VOC.map(v => [v[0], v[1], v[2]]), "Les mots-clés des invocations et du Coran. Touchez une carte pour afficher la réponse.", true);
  if (m === "phr") return learnList(PHR[lv.p][1], "Lisez chaque expression à voix haute en vous aidant de la translittération.", false);
  if (m === "read") return learnRead();
  if (m === "quiz") return learnQuiz();
}
