  LET.forEach((L, i) => { h += '<button class="lcell' + (st.seen[i] ? " seen" : "") + '" data-i="' + i + '"><span class="lc-ar" lang="ar">' + L[0] + '</span><span class="lc-n">' + L[2] + '</span></button>'; });
