const HARAKAT = [
 ["َ","Fatha","a","Petit trait au-dessus de la lettre : son « a »."],
 ["ِ","Kasra","i","Petit trait au-dessous : son « i »."],
 ["ُ","Damma","u","Petit « و » au-dessus : son « ou »."],
 ["ْ","Soukoun","","Petit rond : la lettre se prononce sans voyelle."],
 ["َّ","Chadda","","Petit « w » : la lettre est doublée (appuyée)."],
 ["ً","Tanwîn fatha","an","Deux fathas : son « an » en fin de mot."],
 ["ٍ","Tanwîn kasra","in","Deux kasras : son « in » en fin de mot."],
 ["ٌ","Tanwîn damma","un","Deux dammas : son « oun » en fin de mot."]
];
function learnVowels(){
  const L = LET[lv.vl], c = L[0], lat = L[3];
  let h = '<div class="lwrap"><p class="lintro">Les voyelles courtes ne sont pas des lettres mais de petits signes placés au-dessus ou au-dessous des lettres. Le Coran et les invocations sont toujours écrits avec ces signes.</p>';
  h += '<div class="lpick" dir="rtl">';
  LET.forEach((x, i) => { if (i === 0) return; h += '<button class="' + (i === lv.vl ? "on" : "") + '" data-v="' + i + '" lang="ar">' + x[0] + '</button>'; });
  h += '</div><div class="vtable">';
  HARAKAT.forEach(v => {
    const shown = v[1] === "Chadda" ? c + "َّ" : c + v[0];
    const tr = v[1] === "Soukoun" ? lat : v[1] === "Chadda" ? lat + lat + "a" : lat + v[2];
    h += '<div class="vrow"><span class="v-ar" lang="ar">' + shown + '</span><span class="v-t"><b>' + v[1] + ' · ' + tr + '</b><small>' + v[3] + '</small></span></div>';
  });
  h += '</div><h3 class="lsec">Les voyelles longues</h3><div class="vtable">';
  [[c + "َا","â","Fatha + alif : « a » long"],[c + "ِي","î","Kasra + yâ' : « i » long"],[c + "ُو","û","Damma + wâw : « ou » long"]].forEach(v => {
    h += '<div class="vrow"><span class="v-ar" lang="ar">' + v[0] + '</span><span class="v-t"><b>' + lat + v[1] + '</b><small>' + v[2] + '</small></span></div>';
  });
  h += '</div><h3 class="lsec">Bon à savoir</h3><div class="vtable">'
    + '<div class="vrow"><span class="v-ar" lang="ar">ء</span><span class="v-t"><b>Hamza</b><small>Un coup de glotte, comme la coupure dans « ah-oh ». Elle se pose souvent sur un alif (أ إ), un wâw (ؤ) ou un yâ\' (ئ).</small></span></div>'
    + '<div class="vrow"><span class="v-ar" lang="ar">ة</span><span class="v-t"><b>Tâ\' marbûṭa</b><small>Un « t » en fin de mot, souvent prononcé « a » quand on s’arrête (رَحْمَة : raḥma).</small></span></div>'
    + '<div class="vrow"><span class="v-ar" lang="ar">لا</span><span class="v-t"><b>Lâm-alif</b><small>Quand lâm est suivi d’alif, les deux lettres forment ce signe unique : « lâ ».</small></span></div>'
    + '<div class="vrow"><span class="v-ar" lang="ar">ال</span><span class="v-t"><b>L’article « al »</b><small>Devant certaines lettres (dites solaires, comme ر س ش ن), le « l » ne se prononce pas et la lettre suivante est doublée : الرَّحْمَن se lit ar-raḥmân.</small></span></div></div></div>';
  main.innerHTML = h;
  main.querySelectorAll("[data-v]").forEach(b => b.onclick = () => { lv.vl = +b.dataset.v; const y = main.scrollTop; learnVowels(); main.scrollTop = y; });
}
let syl = null;
function newSyl(){
  const pool = [];
  for (let n = 0; n < 2 + Math.floor(Math.random() * 2); n++){
    const i = 1 + Math.floor(Math.random() * 27), L = LET[i];
    const k = Math.floor(Math.random() * 6);
    const V = [["َ","a"],["ِ","i"],["ُ","u"],["َا","â"],["ِي","î"],["ُو","û"]][k];
    pool.push([L[0] + V[0], L[3] + V[1]]);
  }
  syl = {ar: pool.map(p => p[0]).join(""), tr: pool.map(p => p[1]).join("-"), shown: false};
}
function learnSyll(){
  if (!syl) newSyl();
  let h = '<div class="lwrap"><p class="lintro">Lisez la syllabe à voix haute, puis vérifiez la réponse. Ces combinaisons servent à s’entraîner et ne sont pas toujours de vrais mots.</p>';
  h += '<div class="scard"><span class="sy-ar" lang="ar">' + syl.ar + '</span><span class="sy-tr">' + (syl.shown ? syl.tr : "?") + '</span></div>';
  h += '<div class="qnav"><button class="btn ghost" id="sShow">Voir la réponse</button><button class="btn" id="sNext">Suivante ›</button></div></div>';
  main.innerHTML = h;
  $("sShow").onclick = () => { syl.shown = true; learnSyll(); };
  $("sNext").onclick = () => { newSyl(); learnSyll(); };
}
function learnList(rows, intro, flip){
  let h = '<div class="lwrap"><p class="lintro">' + esc(intro) + '</p><div class="plist">';
  rows.forEach((r, i) => { h += '<button class="pcard' + (flip ? " flip" : "") + '" data-i="' + i + '"><span class="p-ar" lang="ar">' + r[0] + '</span><span class="p-tr">' + esc(r[1]) + '</span><span class="p-fr">' + esc(r[2]) + '</span></button>'; });
  h += '</div></div>';
  main.innerHTML = h;
  if (flip) main.querySelectorAll(".pcard").forEach(b => b.onclick = () => b.classList.toggle("open"));
}
function learnRead(){
  if (!Q){
    main.innerHTML = '<div class="qwrap"><p class="qmsg">Chargement…</p></div>';
    loadQuran().then(() => { if (cur === "learn" && lv.mode === "read") learnRead(); }).catch(() => { main.innerHTML = '<div class="qwrap"><p class="qmsg">Le texte du Coran n’est pas disponible pour le moment.</p></div>'; });
    return;
  }
  const R = READ[lv.r];
  let h = '<div class="lwrap"><div class="qtabs">';
  READ.forEach((x, i) => { h += '<button data-r="' + i + '" class="' + (i === lv.r ? "on" : "") + '">' + SURA_TR[x.s - 1] + '</button>'; });
  h += '</div><p class="lintro">Touchez ▶ pour écouter chaque verset, puis répétez en suivant le texte arabe et sa translittération.</p><div class="rlist">';
  Q[R.s].forEach((t, i) => {
    let txt = t; if (i === 0 && R.s !== 1){ const m = txt.match(BASM_RE); if (m) txt = txt.slice(m[0].length); }
    h += '<div class="rrow"><button class="rplay" data-g="' + (R.g + i) + '" aria-label="Écouter le verset ' + (i + 1) + '">▶</button><div class="rtx"><p class="r-ar" lang="ar">' + esc(txt) + ' <span class="an">﴿' + an(i + 1) + '﴾</span></p><p class="r-tr">' + esc(R.t[i] || "") + '</p></div></div>';
  });
  h += '</div><p class="qcredit">Texte : Tanzil · Récitation : Mishary Rashid Al-Afasy</p></div>';
  main.innerHTML = h;
  main.querySelectorAll("[data-r]").forEach(b => b.onclick = () => openLearn("read", {r: +b.dataset.r}));
  main.querySelectorAll(".rplay").forEach(b => b.onclick = () => learnPlay(b, QA(+b.dataset.g)));
}
function pickLetter(st){
  const w = LET.map((_, i) => 1 + 3 * (st.miss[i] || 0));
  let r = Math.random() * w.reduce((a, b) => a + b, 0);
  for (let i = 0; i < 28; i++){ r -= w[i]; if (r <= 0) return i; }
  return 27;
}
function newQ(qz){
  const st = LS(), i = pickLetter(st), fi = Math.floor(Math.random() * 4);
  const ch = new Set([i]); while (ch.size < 4) ch.add(Math.floor(Math.random() * 28));
  qz.cur = {i, fi, choices: [...ch].sort(() => Math.random() - .5), ans: null};
}
function learnQuiz(){
  if (!lv.qz){ lv.qz = {n: 0, score: 0}; newQ(lv.qz); }
  const qz = lv.qz;
  if (qz.n >= 10){
    const st = LS(); if (qz.score > st.best){ st.best = qz.score; lsave(st); }
    main.innerHTML = '<div class="lwrap"><div class="scard"><span class="sy-ar">' + qz.score + ' / 10</span><span class="sy-tr">' + (qz.score >= 8 ? "Excellent, mâ shâ'a-llâh !" : qz.score >= 5 ? "Bien ! Continuez à réviser." : "Revoyez l’alphabet, puis réessayez.") + '</span></div><div class="qnav"><button class="btn ghost" id="qzA">Revoir l’alphabet</button><button class="btn" id="qzR">Recommencer</button></div><p class="lnote">Les lettres ratées reviendront plus souvent dans les prochains quiz.</p></div>';
    $("qzA").onclick = () => openLearn("alpha");
    $("qzR").onclick = () => openLearn("quiz", {qz: null});
    return;
  }
  const c = qz.cur, L = LET[c.i], form = forms(L[0])[c.fi];
  let h = '<div class="lwrap"><div class="lprog"><span class="bar"><i style="width:' + (qz.n * 10) + '%"></i></span><span>Question ' + (qz.n + 1) + ' / 10 · score ' + qz.score + '</span></div>';
  h += '<div class="scard"><span class="sy-ar" lang="ar">' + form + '</span><span class="sy-tr">Quelle est cette lettre ? <small>(forme ' + ["isolée","de début","du milieu","de fin"][c.fi] + ')</small></span></div><div class="qchoices">';
  c.choices.forEach(k => {
    let cls = "";
    if (c.ans !== null){ if (k === c.i) cls = "ok"; else if (k === c.ans) cls = "ko"; }
    h += '<button class="qc ' + cls + '" data-k="' + k + '"' + (c.ans !== null ? " disabled" : "") + '>' + LET[k][2] + ' <small>(' + LET[k][3] + ')</small></button>';
  });
  h += '</div>';
  if (c.ans !== null) h += '<div class="qnav"><span></span><button class="btn" id="qzN">' + (qz.n === 9 ? "Voir le résultat" : "Suivante") + ' ›</button></div>';
  h += '</div>';
  main.innerHTML = h;
  main.querySelectorAll(".qc").forEach(b => b.onclick = () => {
    const k = +b.dataset.k; c.ans = k;
    const st = LS();
    if (k === c.i){ qz.score++; if (st.miss[c.i]) st.miss[c.i]--; buzz(false); }
    else { st.miss[c.i] = (st.miss[c.i] || 0) + 1; }
    lsave(st); learnQuiz();
  });
  const nx = $("qzN"); if (nx) nx.onclick = () => { qz.n++; if (qz.n < 10) newQ(qz); learnQuiz(); };
}

function setMode(){
  const home = cur === null;
  app.classList.toggle("is-home", home);
  app.classList.toggle("not-home", !home);
  app.classList.toggle("is-quran", cur === "coran");
  app.classList.toggle("is-learn", cur === "learn");
  const top = home || (cur === "coran" && qv.mode === "list") || (cur === "learn" && lv.mode === "home");
  app.classList.toggle("show-tabs", top);
  app.classList.toggle("top-level", top);
  const tab = home ? "adhkar" : cur === "coran" ? "coran" : cur === "learn" ? "apprendre" : "adhkar";
  document.querySelectorAll(".tabbar [data-tab]").forEach(b => b.classList.toggle("on", b.dataset.tab === tab));
  if (home) root.removeAttribute("data-session"); else root.setAttribute("data-session", cur);
  if (cur === "coran"){ $("sTitleA").textContent = "الْقُرْآنُ الْكَرِيمُ"; $("sTitleF").textContent = qv.mode === "read" ? SURA_TR[qv.s - 1] : "Le Coran"; }
  else if (cur === "learn"){ $("sTitleA").textContent = "تَعَلُّمُ الْعَرَبِيَّةِ"; $("sTitleF").textContent = lv.mode === "phr" ? PHR[lv.p][0] : LTITLE[lv.mode]; }
  else if (!home){ $("sTitleA").textContent = SESS[cur].ar; $("sTitleF").textContent = SESS[cur].fr; }
}

function render(){
  setMode();
  if (cur === null){ renderHome(); main.scrollTop = 0; return; }
  if (cur === "coran"){ renderQuran(); return; }
  if (cur === "learn"){ renderLearn(); return; }
  const list = items(), n = doneCount();
  $("barFill").style.width = (100 * n / list.length) + "%";
  $("progTxt").textContent = n + " / " + list.length;
  if (idx >= list.length){
    main.innerHTML = renderEnd();
    $("bHome").onclick = goHome;
    $("bReview").onclick = () => go(0);
    $("counter").style.visibility = "hidden";
    $("hint").textContent = "";
    $("bPrev").disabled = false; $("bNext").disabled = true;
    return;
  }
  $("counter").style.visibility = "visible";
  main.innerHTML = renderCard(idx);
  main.scrollTop = 0;
  const bp = $("bPlay");
  if (bp) { paintPlay(bp, pl.k === curKey() ? pl.state : "idle"); bp.onclick = toggleAudio; }
  updateCounter();
  $("bPrev").disabled = idx === 0;
  $("bNext").disabled = false;
}

function updateCounter(){
  const it = items()[idx], d = doneOf(idx), left = Math.max(0, it.n - d);
  $("ring").style.strokeDasharray = C;
  $("ring").style.strokeDashoffset = C * (1 - Math.min(d, it.n) / it.n);
  $("counter").classList.toggle("done", left === 0);
  if (left === 0){ $("cBig").textContent = "✓"; $("cSm").textContent = "terminé"; }
  else if (it.n === 1){ $("cBig").textContent = "✓"; $("cSm").textContent = "valider"; }
  else { $("cBig").textContent = left; $("cSm").textContent = "restant" + (left > 1 ? "s" : ""); }
  $("hint").textContent = left === 0 ? "Glissez ou touchez la flèche pour continuer" : (it.n === 1 ? "Touchez le bouton une fois récité" : "Touchez le bouton à chaque répétition");
  $("counter").setAttribute("aria-label", left === 0 ? "Terminé" : "Compter, " + left + " restant");
}

let advTimer = null;
// Retour au comptage : vibration (Android), haptique iOS 18+ (interrupteur natif), son optionnel
function iosHaptic(){
  try {
    const label = document.createElement("label");
    label.setAttribute("aria-hidden", "true");
    label.style.display = "none";
    const input = document.createElement("input");
    input.type = "checkbox";
    input.setAttribute("switch", "");
    label.appendChild(input);
    document.head.appendChild(label);
    label.click();
    document.head.removeChild(label);
  } catch(e){}
}
let actx = null;
function tick(strong){
  try {
    actx = actx || new (window.AudioContext || window.webkitAudioContext)();
    if (actx.state === "suspended") actx.resume();
    const o = actx.createOscillator(), g = actx.createGain(), t = actx.currentTime;
    o.type = "sine"; o.frequency.value = strong ? 660 : 880;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.25, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + (strong ? 0.25 : 0.08));
    o.connect(g).connect(actx.destination); o.start(t); o.stop(t + 0.3);
  } catch(e){}
}
function buzz(strong){
  if (prefs.snd) tick(strong);
  if (!prefs.vib) return;
  if (typeof navigator.vibrate === "function"){ try { if (navigator.vibrate(strong ? [40, 70, 40] : 25)) return; } catch(e){} }
  iosHaptic();
  if (strong) setTimeout(iosHaptic, 150);
}

function tap(){
  if (cur === null || cur === "coran" || cur === "learn" || idx >= items().length) return;
  const it = items()[idx];
  if (doneOf(idx) >= it.n){ go(idx + 1); return; }
  prog().counts[idx] = doneOf(idx) + 1;
  buzz(prog().counts[idx] >= it.n);
  save(); updateCounter();
  const n = doneCount();
  $("barFill").style.width = (100 * n / items().length) + "%";
  $("progTxt").textContent = n + " / " + items().length;
  if (prog().counts[idx] >= it.n){
    clearTimeout(advTimer);
    const at = idx, k = cur;
    advTimer = setTimeout(() => { if (idx === at && cur === k) go(idx + 1); }, 700);
  }
}

function go(i){
  if (cur === null || cur === "coran" || cur === "learn") return;
  clearTimeout(advTimer);
  const chain = autoChain && prefs.auto; autoChain = false;
  stopAudio();
  idx = Math.max(0, Math.min(items().length, i));
  save(); render();
  if (chain && idx < items().length && tracksOf(items()[idx]) && doneOf(idx) < items()[idx].n) startAudio();
}
function openSession(k){
  cur = k; loadProg(k);
  idx = Math.min(prog().idx || 0, items().length);
  if (idx >= items().length && doneCount() < items().length) idx = 0;
  render();
}
function goHome(){ clearTimeout(advTimer); autoChain = false; stopAudio(); save(); cur = null; render(); }

$("counter").addEventListener("click", tap);
$("bNext").addEventListener("click", () => go(idx + 1));
$("bPrev").addEventListener("click", () => go(idx - 1));
function backAction(){
  if (cur === "coran" && qv.mode === "read"){ qv.mode = "list"; render(); main.scrollTop = 0; }
  else if (cur === "learn" && lv.mode !== "home"){ const back = lv.mode === "letter" ? "alpha" : "home"; openLearn(back); }
  else goHome();
}
function setTab(t){
  clearTimeout(advTimer); autoChain = false; stopAudio(); lpReset();
  if (t === "adhkar"){ save(); cur = null; }
  else if (t === "coran"){ cur = "coran"; qv.mode = "list"; }
  else if (t === "apprendre"){ cur = "learn"; lv.mode = "home"; }
  render(); main.scrollTop = 0;
}
document.querySelectorAll(".tabbar [data-tab]").forEach(b => b.onclick = () => b.dataset.tab === "reglages" ? $("bSet").click() : setTab(b.dataset.tab));
$("bBack").addEventListener("click", backAction);

let sx = null, sy = null;
main.addEventListener("touchstart", e => { sx = e.touches[0].clientX; sy = e.touches[0].clientY; }, {passive:true});
main.addEventListener("touchend", e => {
  if (sx === null || cur === null || cur === "coran" || cur === "learn") { sx = sy = null; return; }
  const dx = e.changedTouches[0].clientX - sx, dy = e.changedTouches[0].clientY - sy;
  if (Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy) * 1.5) go(idx + (dx < 0 ? 1 : -1));
  sx = sy = null;
}, {passive:true});
document.addEventListener("keydown", e => {
  if (document.body.classList.contains("open")) { if (e.key === "Escape") closeSheets(); return; }
  if (cur === null) return;
  if (cur === "coran" || cur === "learn"){ if (e.key === "Escape") backAction(); return; }
  if (e.key === "ArrowRight") go(idx + 1);
  else if (e.key === "ArrowLeft") go(idx - 1);
  else if (e.key === "Escape") goHome();
});

function openSheet(id){ closeSheets(); document.body.classList.add("open"); $(id).classList.add("show"); }
function closeSheets(){ document.body.classList.remove("open"); document.querySelectorAll(".sheet").forEach(s => s.classList.remove("show")); }
$("sheetBg").onclick = closeSheets;
document.querySelectorAll("[data-close]").forEach(b => b.onclick = closeSheets);

$("bList").onclick = () => {
  if (cur === null || cur === "coran" || cur === "learn") return;
  let h = "";
  items().forEach((it, i) => {
    const label = it.title ? it.title[0] : it.ar;
    const cnt = it.n > 1 ? Math.min(doneOf(i), it.n) + "/" + it.n : (isDone(i) ? "✓" : "");
    h += '<button class="row' + (isDone(i) ? " ok" : "") + (i === idx ? " cur" : "") + '" data-i="' + i + '"><span class="n">' + (i + 1) + '</span><span class="t">' + esc(label) + '</span><span class="c">' + cnt + '</span></button>';
  });
  $("listBody").innerHTML = h;
  $("listBody").querySelectorAll(".row").forEach(r => r.onclick = () => { closeSheets(); go(+r.dataset.i); });
  openSheet("sheetList");
};
$("bSet").onclick = () => {
  $("bReset").textContent = cur && cur !== "coran" && cur !== "learn" ? "Recommencer" : "Tout recommencer";
  openSheet("sheetSet");
};
$("swTr").onclick = () => { prefs.tr = !prefs.tr; savePrefs(); applyPrefs(); };
$("swFr").onclick = () => { prefs.fr = !prefs.fr; savePrefs(); applyPrefs(); };
$("swVib").onclick = () => { prefs.vib = !prefs.vib; savePrefs(); applyPrefs(); if (prefs.vib) buzz(false); };
$("swAuto").onclick = () => { prefs.auto = !prefs.auto; savePrefs(); applyPrefs(); };
document.querySelectorAll("[data-rate]").forEach(b => b.onclick = () => { prefs.rate = +b.dataset.rate; player.playbackRate = prefs.rate; savePrefs(); applyPrefs(); });
$("swSnd").onclick = () => { prefs.snd = !prefs.snd; savePrefs(); applyPrefs(); if (prefs.snd) tick(false); };
$("sMinus").onclick = () => { prefs.scale = Math.max(0.8, +(prefs.scale - 0.1).toFixed(2)); savePrefs(); applyPrefs(); };
$("sPlus").onclick = () => { prefs.scale = Math.min(1.6, +(prefs.scale + 0.1).toFixed(2)); savePrefs(); applyPrefs(); };
$("bReset").onclick = () => {
  for (const k of (cur && cur !== "coran" && cur !== "learn" ? [cur] : ["matin", "soir"])){ progs[k] = {day: today(), counts: {}, idx: 0}; store.set("wirdi-prog-" + k, progs[k]); }
  idx = 0; closeSheets(); render();
};

document.addEventListener("visibilitychange", () => {
  if (document.hidden) return;
  let changed = false;
  for (const k of ["matin", "soir"]) if (progs[k].day !== today()){ loadProg(k); changed = true; }
  if (changed){ if (cur) idx = 0; render(); }
});

applyPrefs();
render();
if ("serviceWorker" in navigator && location.protocol === "https:" && !/claude\.ai|claudeusercontent/.test(location.hostname)) {
  window.addEventListener("load", () => {
    navigator.serviceWorker.register("sw.js").then(reg => {
      const check = () => reg.update().catch(() => {});
      document.addEventListener("visibilitychange", () => { if (!document.hidden) check(); });
      setInterval(check, 30 * 60 * 1000);
    }).catch(() => {});
    let reloaded = false;
    const hadController = !!navigator.serviceWorker.controller;
    navigator.serviceWorker.addEventListener("controllerchange", () => {
      if (!hadController || reloaded) return;
      reloaded = true; location.reload();
    });
  });
}

